<script setup lang="ts">
type Row=Record<string,any>
const page=ref<'dashboard'|'records'>('dashboard'),user=ref<any>(null),auth=ref<'setup'|'login'|'recover'>('login'),busy=ref(false),progress=ref(''),error=ref(''),notice=ref(''),search=ref(''),rows=ref<Row[]>([]),statuses=ref<any[]>([]),dashboard=ref<any>(null),modal=ref(false),editId=ref<number|null>(null),showPassword=ref(false),confirmPassword=ref('')
const credentials=reactive({username:'',displayName:'',password:'',recoveryKey:'',newPassword:''})
const password=computed({get:()=>auth.value==='recover'?credentials.newPassword:credentials.password,set:v=>auth.value==='recover'?credentials.newPassword=v:credentials.password=v})
const needsConfirmation=computed(()=>auth.value==='setup'||auth.value==='recover')
const empty=()=>({recordDate:new Date().toISOString().slice(0,10),recordNumber:'',clientName:'',contacts:'',location:'',sourceOfInfo:'',proformaNo:'',invoiceNo:'',eventDate:'',orderFormNo:'',deliveryFormNo:'',statusId:0,currency:'TZS',taxRateBasisPoints:0,notes:'',items:[{description:'',quantityX100:100,unitPriceMinor:0}]})
const form=reactive(empty()),subtotal=computed(()=>form.items.reduce((s,i)=>s+Math.round(i.quantityX100*i.unitPriceMinor/100),0)),tax=computed(()=>Math.round(subtotal.value*form.taxRateBasisPoints/10000)),total=computed(()=>subtotal.value+tax.value)
const money=(n:number,c='TZS')=>new Intl.NumberFormat('en-TZ',{style:'currency',currency:c,maximumFractionDigits:2}).format((n||0)/100);const date=(v?:string)=>v?new Intl.DateTimeFormat('en-TZ',{day:'numeric',month:'short'}).format(new Date(`${v}T00:00:00`)):'—';const fail=(m?:string)=>error.value=m||'Something went wrong. Please try again.'
function changeAuth(next:'setup'|'login'|'recover'){auth.value=next;error.value='';confirmPassword.value='';showPassword.value=false}
async function timed<T>(name:string,operation:Promise<T>):Promise<T>{let timer:ReturnType<typeof setTimeout>|undefined;const timeout=new Promise<never>((_,reject)=>{timer=setTimeout(()=>reject(new Error(`${name} is taking longer than 10 seconds.`)),10000)});try{return await Promise.race([operation,timeout])}finally{if(timer)clearTimeout(timer)}}
async function existingWorkspace(){const state:any=await timed('Workspace check',window.api!.auth.status());if(!state.ok)throw new Error(state.error?.message||'Could not check the existing workspace.');if(!state.data.hasUser)return false;if(state.data.user){user.value=state.data.user;void load()}else{changeAuth('login');notice.value='A workspace already exists. Sign in to continue.'}return true}
async function load(){const statusesTask=timed('Statuses',window.api!.statuses.list()).then((r:any)=>{if(!r.ok)throw new Error(r.error.message);statuses.value=r.data});const recordsTask=timed('Records',window.api!.records.list({search:search.value})).then((r:any)=>{if(!r.ok)throw new Error(r.error.message);rows.value=r.data});const dashboardTask=timed('Dashboard',window.api!.dashboard.data()).then((r:any)=>{if(!r.ok)throw new Error(r.error.message);dashboard.value=r.data});const results=await Promise.allSettled([statusesTask,recordsTask,dashboardTask]);const failed=results.find((result):result is PromiseRejectedResult=>result.status==='rejected');if(failed)fail(failed.reason instanceof Error?failed.reason.message:'Workspace data could not be loaded.')}
async function boot(){const r:any=await window.api?.auth.status();if(!r?.ok)return fail(r?.error?.message);user.value=r.data.user;auth.value=r.data.hasUser?'login':'setup';if(user.value)await load()}
async function signIn(){if(needsConfirmation.value&&password.value!==confirmPassword.value)return fail('Passwords do not match.');busy.value=true;error.value='';const action=auth.value;progress.value=action==='setup'?'Creating secure workspace…':action==='recover'?'Resetting password…':'Signing in…';try{let r:any;if(action==='setup'){if(await existingWorkspace()){busy.value=false;return}r=await timed('Workspace creation',window.api!.auth.setup({username:credentials.username,displayName:credentials.displayName,password:credentials.password}))}else if(action==='login')r=await timed('Sign in',window.api!.auth.login({username:credentials.username,password:credentials.password}));else r=await timed('Password reset',window.api!.auth.recover({username:credentials.username,recoveryKey:credentials.recoveryKey,newPassword:credentials.newPassword}));if(!r.ok){busy.value=false;return fail(r.error.message)}if(action==='recover'){busy.value=false;notice.value=`Password reset. New recovery key: ${r.data.recoveryKey}`;changeAuth('login');return}user.value=action==='setup'?r.data.user:r.data;if(action==='setup')notice.value=`Workspace created. Save this recovery key: ${r.data.recoveryKey}`;busy.value=false;progress.value='';void load()}catch(reason){busy.value=false;fail(reason instanceof Error?`${reason.message} Nothing was submitted. Check your details and try again.`:'Workspace creation timed out. Check workspace or try again.')}}
async function logout(){await window.api?.auth.logout();user.value=null;changeAuth('login')}
function newRecord(){Object.assign(form,empty());form.statusId=statuses.value.find(s=>s.is_default)?.id||statuses.value[0]?.id||0;editId.value=null;error.value='';modal.value=true}
async function edit(row:Row){const r:any=await window.api!.records.get(row.id);if(!r.ok||!r.data)return fail(r.error?.message);const x=r.data.record;Object.assign(form,{recordDate:x.record_date,recordNumber:x.record_number||'',clientName:x.client_name,contacts:x.contacts||'',location:x.location||'',sourceOfInfo:x.source_of_info||'',proformaNo:x.proforma_no||'',invoiceNo:x.invoice_no||'',eventDate:x.event_date||'',orderFormNo:x.order_form_no||'',deliveryFormNo:x.delivery_form_no||'',statusId:x.status_id,currency:x.currency,taxRateBasisPoints:x.tax_rate_bp,notes:x.notes||'',items:r.data.items.map((i:any)=>({description:i.description,quantityX100:i.quantity_x100,unitPriceMinor:i.unit_price_minor}))});editId.value=row.id;modal.value=true}
async function save(){if(!form.clientName.trim()||form.items.some(i=>!i.description.trim()))return fail('Enter a client and a description for each line item.');busy.value=true;const record={...form,items:undefined};const r:any=editId.value===null?await window.api!.records.create({record,items:form.items}):await window.api!.records.update({id:editId.value,record,items:form.items});busy.value=false;if(!r.ok)return fail(r.error.message);modal.value=false;notice.value='Record saved.';await load()}
onMounted(boot)
</script>
<template>
<main v-if="user" class="app"><aside><div class="brand"><b>BR</b><span>Business<br><strong>Records</strong></span></div><nav><button :class="{active:page==='dashboard'}" @click="page='dashboard'">▦ Dashboard</button><button :class="{active:page==='records'}" @click="page='records'">▤ Records</button></nav><button class="logout" @click="logout">Sign out</button></aside><section class="content"><header><div><p>{{page==='dashboard'?'OVERVIEW':'RECORD MANAGEMENT'}}</p><h1>{{page==='dashboard'?`Good day, ${user.displayName.split(' ')[0]}`:'Business records'}}</h1></div><button class="primary" @click="newRecord">+ New record</button></header><div v-if="notice" class="notice">{{notice}} <button @click="notice=''">×</button></div><p v-if="error&&!modal" class="error">{{error}}</p><template v-if="page==='dashboard'"><section class="metrics"><article><span>Records today</span><strong>{{dashboard?.recordsToday||0}}</strong><small>Created today</small></article><article><span>This month</span><strong>{{money(dashboard?.monthSummary?.[0]?.total,dashboard?.monthSummary?.[0]?.currency)}}</strong><small>{{dashboard?.monthSummary?.[0]?.count||0}} records</small></article><article><span>Upcoming events</span><strong>{{dashboard?.upcomingEvents?.length||0}}</strong><small>Next 7 days</small></article></section><article class="card"><div class="heading"><div><h2>Recent records</h2><small>Your latest business activity</small></div><button @click="page='records'">View all</button></div><div v-if="rows.length" class="list"><button v-for="r in rows.slice(0,6)" :key="r.id" @click="edit(r)"><i>{{r.client_name.slice(0,1)}}</i><span><strong>{{r.client_name}}</strong><small>{{r.invoice_no||r.record_number||'No reference'}} · {{date(r.record_date)}}</small></span><strong>{{money(r.grand_total_minor,r.currency)}}</strong><em :style="{'--c':r.status_color}">{{r.status_name}}</em></button></div><div v-else class="empty"><strong>No records yet</strong><p>Create your first record to see activity here.</p></div></article></template><template v-else><div class="toolbar"><input v-model="search" placeholder="Search client, record or invoice" @input="load"><span>{{rows.length}} records</span></div><article class="card table"><table><thead><tr><th>CLIENT</th><th>REFERENCE</th><th>DATE</th><th>STATUS</th><th>TOTAL</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.client_name}}</strong><small>{{r.contacts||'No contact details'}}</small></td><td>{{r.invoice_no||r.record_number||'—'}}</td><td>{{date(r.record_date)}}</td><td><em :style="{'--c':r.status_color}">{{r.status_name}}</em></td><td><strong>{{money(r.grand_total_minor,r.currency)}}</strong></td><td><button @click="edit(r)">Edit</button></td></tr></tbody></table><div v-if="!rows.length" class="empty">No matching records.</div></article></template></section></main>
<main v-else class="auth"><section class="intro"><div class="brand"><b>BR</b><span>Business<br><strong>Records</strong></span></div><div><p>OFFLINE BUSINESS MANAGEMENT</p><h1>Your business,<br>organized.</h1><span>Securely manage records, invoices, events, and client activity from one private desktop workspace.</span></div><small>Local data · Private by design</small></section><form @submit.prevent="signIn"><p>{{auth==='setup'?'WELCOME':auth==='recover'?'ACCOUNT RECOVERY':'WELCOME BACK'}}</p><h2>{{auth==='setup'?'Create your workspace':auth==='recover'?'Reset your password':'Sign in to continue'}}</h2><label v-if="auth==='setup'">Your name<input v-model="credentials.displayName" required></label><label>Username<input v-model="credentials.username" required></label><label v-if="auth==='recover'">Recovery key<input v-model="credentials.recoveryKey" required></label><label>{{auth==='recover'?'New password':'Password'}}<span class="password"><input v-model="password" :type="showPassword?'text':'password'" minlength="6" required><button type="button" @click="showPassword=!showPassword">{{showPassword?'Hide':'Show'}}</button></span></label><label v-if="needsConfirmation">Confirm password<span class="password"><input v-model="confirmPassword" :type="showPassword?'text':'password'" minlength="6" required><button type="button" @click="showPassword=!showPassword">{{showPassword?'Hide':'Show'}}</button></span></label><p v-if="needsConfirmation&&confirmPassword&&password!==confirmPassword" class="error">Passwords do not match.</p><p v-else-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">{{busy?progress:auth==='setup'?'Create workspace':auth==='recover'?'Reset password':'Sign in'}}</button><button v-if="auth!=='login'" type="button" @click="changeAuth('login')">Back to sign in</button><button v-if="auth==='login'" type="button" @click="changeAuth('recover')">Forgot password?</button></form></main>
<div v-if="modal" class="shade" @mousedown.self="modal=false"><section class="modal"><header><div><p>{{editId===null?'NEW RECORD':'EDIT RECORD'}}</p><h2>{{editId===null?'Create business record':'Update business record'}}</h2></div><button @click="modal=false">×</button></header><form @submit.prevent="save"><div class="body"><p v-if="error" class="error">{{error}}</p><fieldset><legend>Record details</legend><div class="fields"><label>Client name *<input v-model="form.clientName" required></label><label>Record date *<input v-model="form.recordDate" type="date"></label><label>Record number<input v-model="form.recordNumber"></label><label>Status<select v-model.number="form.statusId"><option v-for="s in statuses" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Contact details<input v-model="form.contacts"></label><label>Location<input v-model="form.location"></label></div></fieldset><fieldset><legend>Document references</legend><div class="fields"><label>Proforma number<input v-model="form.proformaNo"></label><label>Invoice number<input v-model="form.invoiceNo"></label><label>Order form number<input v-model="form.orderFormNo"></label><label>Delivery form number<input v-model="form.deliveryFormNo"></label><label>Event date<input v-model="form.eventDate" type="date"></label><label>Source<input v-model="form.sourceOfInfo"></label></div></fieldset><fieldset><div class="heading"><legend>Line items</legend><button type="button" @click="form.items.push({description:'',quantityX100:100,unitPriceMinor:0})">+ Add line</button></div><div v-for="(i,n) in form.items" :key="n" class="item"><input v-model="i.description" required placeholder="Item or service"><input v-model.number="i.quantityX100" type="number" min="1"><input v-model.number="i.unitPriceMinor" type="number" min="0"><strong>{{money(Math.round(i.quantityX100*i.unitPriceMinor/100),form.currency)}}</strong><button type="button" :disabled="form.items.length===1" @click="form.items.splice(n,1)">×</button></div><div class="totals"><label>Currency<select v-model="form.currency"><option>TZS</option><option>USD</option><option>EUR</option><option>KES</option></select></label><label>Tax (basis points)<input v-model.number="form.taxRateBasisPoints" type="number" min="0"></label><strong>Subtotal {{money(subtotal,form.currency)}} · Tax {{money(tax,form.currency)}} · Total {{money(total,form.currency)}}</strong></div></fieldset><fieldset><legend>Notes</legend><textarea v-model="form.notes" rows="3"></textarea></fieldset></div><footer><button type="button" @click="modal=false">Cancel</button><button class="primary" :disabled="busy">{{busy?'Saving…':'Save record'}}</button></footer></form></section></div>
</template>
<style scoped>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#f5f7fb;color:#172033;font:14px system-ui,sans-serif}.app{display:flex;min-height:100vh}aside{width:240px;background:#111d31;color:#b4c0d1;padding:28px 16px;display:flex;flex-direction:column}.brand{display:flex;gap:10px;align-items:center;color:white;line-height:1.05}.brand>b{display:grid;place-items:center;width:38px;height:38px;border-radius:10px;background:#24a36d;color:#062c1b;font-size:12px}.brand strong{font-size:17px}nav{display:grid;gap:6px;margin-top:48px}nav button,.logout{border:0;background:transparent;color:#b4c0d1;text-align:left;padding:12px;border-radius:8px;font:inherit;cursor:pointer}nav button.active{background:#253650;color:white}.logout{margin-top:auto}.content{flex:1;min-width:0;max-width:1500px;margin:auto;padding:34px 42px}.content>header,.heading{display:flex;justify-content:space-between;align-items:flex-start}.content>header{margin-bottom:28px}.content header p,.auth form>p,.intro p,.modal header p{margin:0 0 7px;color:#74849a;font-size:11px;font-weight:800;letter-spacing:.1em}.content h1{margin:0;font-size:28px}.primary{border:0;border-radius:8px;background:#16875d;color:white;padding:11px 16px;font:inherit;font-weight:750;cursor:pointer}.primary:disabled{opacity:.6}.notice,.error{padding:11px 14px;border-radius:8px;margin:0 0 17px}.notice{background:#e3f5ed;color:#126244}.notice button{float:right;border:0;background:transparent}.error{background:#fff0ef;color:#a62d28}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:18px}.metrics article,.card{background:white;border:1px solid #e2e8f0;border-radius:12px}.metrics article{padding:20px}.metrics span,.metrics small,small{display:block;color:#75849a}.metrics strong{display:block;font-size:26px;margin:8px 0}.card{padding:20px}.heading h2,legend{margin:0;font-size:16px}.heading button,.table button{border:0;background:transparent;color:#16875d;font:inherit;font-weight:700;cursor:pointer}.list{margin-top:15px}.list button{width:100%;display:grid;grid-template-columns:34px 1fr auto auto;gap:11px;align-items:center;border:0;border-top:1px solid #edf0f4;background:transparent;text-align:left;padding:12px 2px;cursor:pointer}.list i{display:grid;place-items:center;background:#dff4ea;color:#167451;width:32px;height:32px;border-radius:50%;font-style:normal;font-weight:800}.list small{display:block}.list em,td em{--c:#64748b;font-style:normal;background:color-mix(in srgb,var(--c) 13%,white);color:var(--c);padding:5px 8px;border-radius:99px;font-size:11px;font-weight:800}.toolbar{display:flex;justify-content:space-between;margin-bottom:16px}.toolbar input{width:400px;max-width:70vw;border:1px solid #dce3ec;border-radius:8px;padding:11px;font:inherit}.table{padding:0;overflow:auto}table{width:100%;border-collapse:collapse}th{text-align:left;padding:15px 20px;background:#fafbfd;color:#7f8da2;font-size:10px}td{padding:16px 20px;border-top:1px solid #edf0f4}.empty{text-align:center;padding:35px;color:#728198}.auth{min-height:100vh;display:grid;grid-template-columns:1fr 1fr}.intro{padding:64px clamp(32px,8vw,150px);background:#122039;color:white;display:flex;flex-direction:column;justify-content:space-between}.intro h1{font-size:clamp(40px,5vw,62px);line-height:1.02}.intro span{color:#b8c6d9;font-size:17px;line-height:1.65}.auth form{width:min(420px,calc(100% - 48px));align-self:center;justify-self:center;display:grid;gap:14px}.auth form h2{margin:0 0 10px;font-size:29px}.auth label,.fields label,.totals label{display:grid;gap:6px;color:#405066;font-size:12px;font-weight:750}.auth input,.fields input,.fields select,.item input,.totals input,.totals select,textarea{border:1px solid #dbe3ec;border-radius:7px;padding:10px;font:inherit}.password{display:flex}.password input{min-width:0;flex:1;border-radius:7px 0 0 7px}.password button{border:1px solid #dbe3ec;border-left:0;border-radius:0 7px 7px 0;background:#f4f7f9;color:#167451;font-weight:700;cursor:pointer}.auth form>button:not(.primary){border:0;background:transparent;color:#16875d;text-align:left;font:inherit;font-weight:700;cursor:pointer}.shade{position:fixed;inset:0;z-index:4;background:#102036aa;display:grid;place-items:center;padding:22px}.modal{width:min(1000px,100%);max-height:calc(100vh - 44px);display:flex;flex-direction:column;background:white;border-radius:14px;overflow:hidden}.modal header,.modal footer{padding:18px 25px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e7edf2}.modal header h2{margin:0}.modal header button,.modal footer button{border:0;border-radius:7px;padding:9px 13px;font:inherit;cursor:pointer}.body{overflow:auto;padding:8px 25px 24px}fieldset{border:0;border-bottom:1px solid #e9edf2;padding:20px 0;margin:0}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:14px}.item{display:grid;grid-template-columns:1.6fr .7fr .9fr .8fr 28px;gap:8px;align-items:center;margin-top:9px}.item button{border:0;background:transparent;color:#b64242;font-size:20px}.totals{display:flex;gap:13px;justify-content:flex-end;margin-top:18px}.totals label{width:120px}.modal footer{justify-content:flex-end;gap:9px;border-top:1px solid #e7edf2;border-bottom:0}@media(max-width:800px){aside{width:64px;padding:20px 10px}.brand span{display:none}.content{padding:25px 20px}.metrics,.fields{grid-template-columns:1fr 1fr}.auth{grid-template-columns:1fr}.intro{display:none}}@media(max-width:550px){.metrics,.fields{grid-template-columns:1fr}.list button{grid-template-columns:32px 1fr auto}.list em{display:none}.item{grid-template-columns:1fr 1fr 1fr 28px}.item input:first-child{grid-column:span 3}.totals{flex-wrap:wrap}.content{padding:20px 14px}}
</style>
